  (null, 'Circuito HIIT', 'Cardio', 'Peso corporal', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/burpee.mp4', 'Alterne exercícios intensos e curtos períodos de recuperação, mantendo boa técnica mesmo na fadiga.'),
  (null, 'Mobilidade de quadril', 'Mobilidade', 'Peso corporal', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hip-circles-stretch.mp4', 'Faça movimentos lentos de flexão, extensão e rotação do quadril, sem forçar dor.'),
