  (null, 'Puxada alta com triângulo', 'Costas', 'Máquina', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-close-grip-front-lat-pulldown.mp4', 'Use a barra triângulo com pegada neutra, puxe até o peito levando os cotovelos para baixo e retorne controlando.'),
