  (null, 'Remada baixa com triângulo', 'Costas', 'Cabo', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-straight-back-seated-row-v-grip.mp4', 'Puxe o triângulo em direção ao abdômen mantendo o tronco ereto e os cotovelos próximos ao corpo.'),
