  (null, 'Crossover no pulley', 'Peito', 'Cabo', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-fly-crossover-fly.mp4', 'Em pé, cruze as mãos à frente do peito com leve flexão dos cotovelos e retorne devagar.'),
